mapper.insert:

    SELECT SEQ_PLAYLISTS.NEXTVAL FROM DUAL

INSERT INTO PLAYLISTS (
    PLAYLIST_ID, USER_ID, TITLE, DESCRIPTION,
    COVER_IMAGE_URL, PUBLIC_YN
) VALUES (
    #{playlistId}, #{userId}, #{title}, #{description},
    #{coverImageUrl}, #{publicYn}
)

mapper.select:
SELECT * FROM PLAYLISTS
WHERE USER_ID = #{userId}
ORDER BY CREATED_AT DESC

mapper.update:
UPDATE PLAYLISTS
SET PUBLIC_YN = #{publicYn},
    UPDATED_AT = SYSTIMESTAMP
WHERE PLAYLIST_ID = #{playlistId}
  AND USER_ID = #{userId}

mapper.delete:
DELETE FROM PLAYLISTS
WHERE PLAYLIST_ID = #{playlistId}
AND USER_ID = #{userId}

mapper.select:
SELECT * FROM (
    SELECT ROWNUM AS RN, P.* FROM (
        SELECT * FROM PLAYLISTS
        WHERE PUBLIC_YN = 'Y'
        ORDER BY CREATED_AT DESC
    ) P
    WHERE ROWNUM <= #{offset} + #{size}
)
WHERE RN > #{offset}
